package com.judicialai.desktop.design.theme

import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.graphics.ImageBitmap
import androidx.compose.ui.graphics.toComposeImageBitmap
import org.jetbrains.skia.Image
import java.util.Base64

/**
 * 应用 Logo（内嵌 Base64 WebP，256×256，蓝色渐变圆角方块 + 白色天平与文书徽标）。
 * 用于启动页、窗口图标；打包安装器图标（icon.ico）单独配置在 build.gradle.kts。
 * Skia Image.makeFromEncoded 支持 WebP 解码。
 */
object AppLogo {
    private val LOGO_B64: String = """

    """.trimIndent().replace("\n", "")

    val bytes: ByteArray by lazy { Base64.getDecoder().decode(LOGO_B64) }

    val imageBitmap: ImageBitmap by lazy {
        Image.makeFromEncoded(bytes).toComposeImageBitmap()
    }
}

@Composable
fun rememberAppLogo(): ImageBitmap = remember { AppLogo.imageBitmap }
